import { Component } from '@angular/core';

@Component({
  selector: 'featured-brands',
  templateUrl: './featured-brands.component.html',
  styleUrls: ['./featured-brands.component.css']
})
export class FeaturedBrandsComponent {

}
<div class="ekart-featured-product-item">
  <ng-content select=".title"></ng-content>
  <p class="description">
    Discover the latest Nike Air Max shoes designed for comfort and style. Perfect for everyday wear and performance.
  </p>
  <ng-content select=".call-to-action"></ng-content>
</div>
